    {"id": 7, "name": "Sunita Rao", "status": "answered", "duration_secs": 59, "summary": "Rescheduled to Monday."},
    {"id": 7, "name": "Sunita Rao", "status": "answered", "duration_secs": 59, "summary": "Rescheduled to Monday."}
  ];

  // Deduplicate records by ID and name
  function deduplicateData(records) {
    const seen = new Set();
    return records.filter(call => {
      const key = `${call.id}-${call.name || 'unknown'}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }

  // Normalize name capitalization
  function normalizeName(name) {
    if (!name || typeof name !== 'string') return "Unknown";
    return name
      .trim()
      .split(/\s+/)
      .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
      .join(' ');
  }

  // Safely escape HTML to prevent XSS
  function escapeHtml(text) {
    if (!text || typeof text !== 'string') return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  // Sanitize summary but preserve safe HTML tags
  function sanitizeSummary(html) {
    if (!html || typeof html !== 'string') return '';
    const div = document.createElement('div');
    div.innerHTML = html;
    const temp = document.createElement('div');
    const walker = document.createTreeWalker(div, NodeFilter.SHOW_ALL, null, false);
    let node;
    while (node = walker.nextNode()) {
      if (node.nodeType === Node.TEXT_NODE) {
        temp.appendChild(document.createTextNode(node.textContent));
      } else if (node.nodeType === Node.ELEMENT_NODE && ['B', 'STRONG', 'I', 'EM', 'BR'].includes(node.nodeName)) {
        temp.appendChild(node.cloneNode(true));
      }
    }
    return temp.innerHTML;
  }

  // Validate and normalize data
  function validateData(records) {
    return records.map(call => ({
      id: typeof call.id === 'number' ? call.id : 0,
