<script>
  const rawData = [
    {"id": 1, "name": "Anita Sharma", "status": "answered", "duration_secs": 137, "summary": "Booked a follow-up for Friday."},
    {"id": 2, "name": "Rahul Shah", "status": "failed", "duration_secs": 0, "summary": ""},
    {"id": 3, "name": null, "status": "answered", "duration_secs": 64, "summary": "Asked about clinic timings."},
    {"id": 4, "name": "Mohammed Irfan Abdul Rahman Siddiqui", "status": "answered", "duration_secs": 3725, "summary": "Called about his mother's knee surgery. Wanted to know the cost, how many days she would stay, whether insurance is accepted, what to bring on the day, and if the doctor could call him back personally before he decides. Asked the same questions again for his father."},
    {"id": 5, "name": "priya nair", "status": "no_answer", "duration_secs": 0, "summary": ""},
    {"id": 6, "name": "Deepak Verma", "status": "answered", "duration_secs": 212, "summary": "Said the doctor was <b>very</b> helpful."},
    {"id": 7, "name": "Sunita Rao", "status": "answered", "duration_secs": 59, "summary": "Rescheduled to Monday."}
  ];

  // Normalize name capitalization
  function normalizeName(name) {
    if (!name || typeof name !== 'string') return null;
    return name
      .trim()
      .split(/\s+/)
      .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
      .join(' ');
  }

  // Validate and normalize data
  function validateData(records) {
    return records.map(call => ({
      id: typeof call.id === 'number' ? call.id : 0,
      name: call.name ? normalizeName(call.name) : null,
      searchName: call.name ? normalizeName(call.name).toLowerCase() : "unknown caller",
      status: typeof call.status === 'string' ? call.status : 'unknown',
      duration_secs: typeof call.duration_secs === 'number' ? Math.max(0, call.duration_secs) : 0,
      summary: typeof call.summary === 'string' ? call.summary.trim() : ''
    }));
  }

  const data = validateData(rawData);
  let currentSort = 'default';
  let sortedData = [...data];

  const statusIcons = {
    'answered': '✓',
    'failed': '✕',
    'no_answer': '☎'
  };

  const statusLabels = {
    'answered': 'Answered',
    'failed': 'Failed',
    'no_answer': 'No answer'
  };

  function formatDuration(secs) {
    if (secs === 0) return "—";
    const h = Math.floor(secs / 3600);
    const m = Math.floor((secs % 3600) / 60);
    const s = secs % 60;

    let parts = [];
    if (h > 0) parts.push(`${h}h`);
    if (m > 0) parts.push(`${m}m`);
    if (s > 0) parts.push(`${s}s`);

    return parts.join(' ') || "0s";
  }

  function sortData(sortType) {
    let sorted = [...data];

    if (sortType === 'name') {
      sorted.sort((a, b) => {
        const nameA = a.searchName;
        const nameB = b.searchName;
        return nameA.localeCompare(nameB);
      });
    } else if (sortType === 'status') {
      const statusOrder = { 'answered': 0, 'failed': 1, 'no_answer': 2, 'unknown': 3 };
      sorted.sort((a, b) => {
        const orderA = statusOrder[a.status] ?? 3;
        const orderB = statusOrder[b.status] ?? 3;
        return orderA - orderB;
      });
    } else if (sortType === 'duration') {
      sorted.sort((a, b) => b.duration_secs - a.duration_secs);
    }

    return sorted;
  }

  const listContainer = document.getElementById('call-list');
  const searchInput = document.getElementById('search-input');
  const searchClear = document.getElementById('search-clear');
  const resultCount = document.getElementById('result-count');
  const sortButtons = document.querySelectorAll('.sort-btn');

  function updateResultCount(total, filtered) {
    if (filtered === 0 && total === 0) {
      resultCount.textContent = '';
    } else if (filtered === 0) {
      resultCount.textContent = '';
    } else {
      resultCount.textContent = `Showing ${filtered} of ${total} ${total === 1 ? 'call' : 'calls'}`;
    }
  }

  function renderList(filterText = "") {
    listContainer.innerHTML = "";

    const trimmedFilter = filterText.trim().toLowerCase();

    let filtered;
    if (trimmedFilter === '') {
      filtered = sortedData;
    } else {
      filtered = sortedData.filter(call => {
        return call.searchName.includes(trimmedFilter);
      });
    }

    updateResultCount(data.length, filtered.length);

    if (filtered.length === 0 && data.length === 0) {
      // No data at all
      const emptyCard = document.createElement('div');
      emptyCard.className = 'empty-state';
      emptyCard.innerHTML = `
        <div class="empty-state-title">No call data</div>
        <div class="empty-state-hint">There are no calls to display.</div>
      `;
      listContainer.appendChild(emptyCard);
      return;
    }

    if (filtered.length === 0) {
      // Search resulted in no matches
      const emptyCard = document.createElement('div');
      emptyCard.className = 'empty-state';
      const displayText = filterText.trim() ? `"${filterText.trim()}"` : '';
      emptyCard.innerHTML = `
        <div class="empty-state-title">No calls found for ${displayText}</div>
        <div class="empty-state-hint">Check the spelling or try fewer letters</div>
        <button class="empty-state-button" id="clear-from-empty">Clear Search</button>
      `;
      listContainer.appendChild(emptyCard);

      const clearBtn = emptyCard.querySelector('#clear-from-empty');
      clearBtn.addEventListener('click', () => {
        searchInput.value = '';
        searchClear.classList.add('hidden');
        searchInput.focus();
        renderList('');
      });
      return;
    }

    // Render calls
    filtered.forEach(call => {
      const card = document.createElement('div');
      card.className = 'call-card';

      const displayName = call.name || "Unknown caller";
      const nameClass = !call.name ? "call-name unknown" : "call-name";

      const statusIcon = statusIcons[call.status] || '?';
      const statusLabel = statusLabels[call.status] || 'Unknown';

      const summaryText = call.summary;
      const hasSummary = summaryText && summaryText.length > 0;

      // Build HTML
      const nameDiv = document.createElement('div');
      nameDiv.className = nameClass;
      nameDiv.textContent = displayName;

      const headerDiv = document.createElement('div');
      headerDiv.className = 'call-header';
      headerDiv.appendChild(nameDiv);

      const metaDiv = document.createElement('div');
      metaDiv.className = 'call-meta';

      const statusBadge = document.createElement('div');
      statusBadge.className = `status-badge ${call.status}`;
      statusBadge.innerHTML = `<span class="status-icon">${statusIcon}</span>${statusLabel}`;
      metaDiv.appendChild(statusBadge);

      const durationBadge = document.createElement('div');
      durationBadge.className = 'duration-badge';
      durationBadge.innerHTML = `<span>⏳</span>${formatDuration(call.duration_secs)}`;
      metaDiv.appendChild(durationBadge);

      headerDiv.appendChild(metaDiv);
      card.appendChild(headerDiv);

      // Summary section
      let toggleCheck = null;

      if (hasSummary) {
        const summaryDiv = document.createElement('div');
        summaryDiv.className = 'call-summary';

        const summaryTextEl = document.createElement('div');
        summaryTextEl.className = 'summary-text';
        summaryTextEl.textContent = summaryText;
        summaryDiv.appendChild(summaryTextEl);

        const toggleBtn = document.createElement('button');
        toggleBtn.type = 'button';
        toggleBtn.className = 'toggle-summary';
        toggleBtn.textContent = 'Read more';
        toggleBtn.setAttribute('aria-expanded', 'false');
        toggleBtn.hidden = true; // shown only if text is actually clamped
        summaryDiv.appendChild(toggleBtn);

        toggleBtn.addEventListener('click', () => {
          const expanded = summaryTextEl.classList.toggle('expanded');
          toggleBtn.textContent = expanded ? 'Show less' : 'Read more';
          toggleBtn.setAttribute('aria-expanded', String(expanded));
        });

        // Must run after the card is in the DOM so heights can be measured
        toggleCheck = () => {
          if (summaryTextEl.scrollHeight > summaryTextEl.clientHeight + 1) {
            toggleBtn.hidden = false;
          }
        };

        card.appendChild(summaryDiv);
      } else {
        const noSummaryDiv = document.createElement('div');
        noSummaryDiv.className = 'call-summary empty';
        noSummaryDiv.textContent = 'No summary';
        card.appendChild(noSummaryDiv);
      }

      listContainer.appendChild(card);
      if (toggleCheck) toggleCheck();
    });
  }

  // Sort button handlers
  sortButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      sortButtons.forEach(b => {
        b.classList.remove('active');
        b.setAttribute('aria-pressed', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-pressed', 'true');
      currentSort = btn.dataset.sort;
      sortedData = sortData(currentSort);
      renderList(searchInput.value);
    });
  });

  // Search input handler
  searchInput.addEventListener('input', (e) => {
    const value = e.target.value;
    if (value.trim()) {
      searchClear.classList.remove('hidden');
    } else {
      searchClear.classList.add('hidden');
    }
    renderList(value);
  });

  // Clear button handler
  searchClear.addEventListener('click', (e) => {
    e.preventDefault();
    searchInput.value = '';
    searchClear.classList.add('hidden');
    searchInput.focus();
    renderList('');
  });

  // Initial render
  sortedData = sortData(currentSort);
  renderList();
</script>
